var configValidateCmd = &cobra.Command{
	Annotations: map[string]string{reference.Result: "The command prints:\n\n```ansi\n$ osapi config validate\n\x1b[1;38;2;0;213;255mConfig:\x1b[0m\n  \x1b[38;2;10;143;176mFile:\x1b[0m   /etc/osapi/osapi.yaml\n  \x1b[38;2;10;143;176mValid:\x1b[0m  yes\n\n\x1b[1;38;2;255;0;255mProblems (0):\x1b[0m\n  \x1b[38;2;138;138;138mNone.\x1b[0m\n```\n\nWith `--json`, the command prints:\n\n```json\n{\n  \"file\": \"/etc/osapi/osapi.yaml\",\n  \"valid\": true,\n  \"problems\": []\n}\n```"},
	Args:        cobra.NoArgs,
	Example:     "  osapi config validate\n  osapi config validate -f ./osapi.yaml --json",
	Long:        "The command starts nothing. It exits 1 when the config is not valid, and\nlists each problem with its rule, the key and the message, then the fix of\neach rule. Each problem in `--json` has `rule`, `key` (when the problem is\nabout one key), `message` and `fix`. `osapi config list` shows each key,\nwith its type, rule and default.\n\nThe rules:\n\n- `file`: The config file exists, and osapi can read it. Fix: Give the path with -f, or put the file at /etc/osapi/osapi.yaml. Check that the user that runs osapi can read it.\n- `parse`: The file is YAML, and each value has the type of its key. Fix: Correct the YAML at the line that the message names. osapi config list shows the type of each key.\n- `value`: Each value passes the validate rule of its key, with the defaults and the environment applied. Fix: Set the key to a value that its rule allows. osapi config get --key <key> shows its rule, type and default.\n- `setting`: Each setting of a behavior, under behaviors.<name>, passes its validate rule. Fix: Set the key to a value that its rule allows. osapi dsl behavior get --name <name> lists the settings of the behavior.\n- `bucket`: Each NATS bucket has its own name. A shared bucket mixes the keys of two roles. Fix: Give one of the two keys that the message names a different bucket.\n- `vault`: Each vault of controller.secrets.vaults has its own name and its own key_file, a type of vault that osapi knows, a config block that its type takes, and what its type needs, such as the key of a nats vault. Fix: Correct the vault that the message names. osapi config get --key controller.secrets.vaults describes a vault, and the message names the types and the settings that there are.\n- `reference`: Each reference, secret://<vault>/<key>, is in a secret field that can take one, and names a vault of controller.secrets.vaults and a key of 1 to 128 letters, digits, - or _. A NATS password cannot be a reference, because osapi needs it to connect to NATS before it can read a vault. Fix: Add the vault that the reference names to controller.secrets.vaults, or correct the reference. For a NATS password, put the value in the file or in its environment variable.\n",
	RunE: func(cmd *cobra.Command, _ []string) error {
		return clicommand.Run(cmd, config.Group, "validate", config.ValidateInput{})
	},
	Short: "Check a config file before osapi starts with it",
	Use:   "validate",
}

func init() {
	configGetCmd.Flags().String("key", "", "The setting to show, such as controller.api.port")
	_ = configGetCmd.MarkFlagRequired("key")
	clicommand.AddCommands(config.Group, configListCmd, configGetCmd, configSpecGetCmd, configValidateCmd)
}
